public class Car {
    private String make;
    private String model;
    private int year;

    /**
     * Constructor to initialize a Car object with make, model, and year.
     * 
     * @param make  the car's make
     * @param model the car's model
     * @param year  the car's year (must be non-negative)
     */
    public Car(String make, String model, int year) {
        if (year < 0) {
            throw new IllegalArgumentException("Year cannot be negative");
        }
        if (isBlank(make) || isBlank(model)) {
            throw new IllegalArgumentException("Make and model cannot be blank");
        }
        this.make = make;
        this.model = model;
        this.year = year;
    }

    private boolean isBlank(String s) {
        return s == null || s.trim().isEmpty();
    }

    /**
     * Get the car's make.
     * 
     * @return the car's make
     */
    public String getMake() {
        return make;
    }

    /**
     * Get the car's model.
     * 
     * @return the car's model
     */
    public String getModel() {
        return model;
    }

    /**
     * Get the car's year.
     * 
     * @return the car's year
     */
    public int getYear() {
        return year;
    }

    @Override
    public String toString() {
        return String.format("%s %s (%d)", make, model, year);
    }
}
```

